import pytest

from bedrock_protocol import v2225

# generated by gophertunnel b8bd735:
# &packet.SetDefaultGameType{GameType: packet.GameTypeSpectator}
SPECTATOR = bytes.fromhex("0c")

# generated by gophertunnel b8bd735:
# &packet.SetDefaultGameType{GameType: -1}
UNDEFINED = bytes.fromhex("01")

GOLDENS = [
    pytest.param(v2225.SetDefaultGameTypePacket(default_game_type=v2225.GameType.SPECTATOR), SPECTATOR, id="spectator"),
    pytest.param(v2225.SetDefaultGameTypePacket(default_game_type=v2225.GameType.UNDEFINED), UNDEFINED, id="undefined"),
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_default_game_type_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_default_game_type_decodes_from_its_golden(packet, golden):
    assert v2225.SetDefaultGameTypePacket.from_bytes(golden) == packet
